      <p>来源已发布及原人员科室仍一致，只表示来源治理可纳入，不能代替人员资质本身、可用性、全部工时规则或排班可行性。</p>
      <el-form inline @submit.prevent="page=1;load()"><el-form-item label="排班原来源科室"><el-select  :model-value="department" @update:model-value="department=$event||null" aria-label="排班原来源科室" clearable filterable :disabled="!!departmentId||saving" :placeholder="governance?'全院审计，可明确限定科室':'请选择实际授权科室'"><el-option v-for="row in departments" :key="row.department_id" :value="row.department_id" :label="`${row.name||'原科室'} · #${row.department_id}`" /><el-option v-if="departmentId&&!departments.some(row=>row.department_id===departmentId)" :value="departmentId" :label="`原科室 #${departmentId}`" /></el-select></el-form-item><el-form-item label="排班原来源类型"><el-select v-model="kind" aria-label="排班原来源类型" :disabled="saving"><el-option v-for="(spec,key) in rosterSourceKinds" :key="key" :value="key" :label="spec.label" /></el-select></el-form-item><el-form-item label="原医生ID过滤"><el-input v-model="doctorFilter" aria-label="原医生ID过滤" inputmode="numeric" clearable /></el-form-item><el-form-item label="排班来源状态过滤"><el-select v-model="status" aria-label="排班来源状态过滤" clearable><el-option v-for="(label,key) in rosterSourceStates" :key="key" :value="key" :label="label" /></el-select></el-form-item><el-button native-type="submit" :loading="loading">查询排班原来源</el-button></el-form>
      <p v-if="error" role="alert">{{ error }}</p><p v-if="notice">{{ notice }}</p><p v-if="!department&&!governance">请明确选择科室后再读取来源或登记。</p>
