      <p v-if="detail.reviewed_at">原审核 {{ detail.reviewed_at }} · 审核人 #{{ detail.reviewed_by }}<br />{{ detail.review_basis_note }}</p><p v-if="detail.revoked_at">原撤销 {{ detail.revoked_at }} · 撤销人 #{{ detail.revoked_by }}<br />{{ detail.revoke_reason }}</p>
      <template v-if="canReview"><el-input v-model="reviewBasis" aria-label="排班原来源审核依据" type="textarea" maxlength="4000" placeholder="至少20个非空白字符且总量不超过4000字节；明确审核原件及适用范围" /><el-button type="primary" :loading="acting" :disabled="acting||!rosterReviewBasisValid(reviewBasis)" @click="act('publish')">审核并发布此原来源</el-button><el-button type="warning" :loading="acting" :disabled="acting||!rosterReviewBasisValid(reviewBasis)" @click="act('reject')">审核并拒绝此原来源</el-button></template>
      <template v-if="detail.can_revoke===true"><el-input v-model="reason" aria-label="排班原来源撤销依据" type="textarea" maxlength="1000" /><el-button type="danger" :loading="acting" :disabled="acting||!reason.trim()" @click="act('revoke')">撤销此排班原来源</el-button></template>
    </template></el-dialog>
  </section>
</template>
<script setup>
