const scope=()=>supportCanonical([props.departmentId,props.governance,props.active,store.state.user.accessToken,store.state.user.username,roles.value]),capture=()=>({epoch,scope:scope()}),current=ticket=>alive&&!paused&&allowed.value&&ticket.epoch===epoch&&ticket.scope===scope(),queryKey=()=>supportCanonical([department.value,kind.value,doctorFilter.value,status.value,page.value]);
const canRecord=computed(()=>allowed.value&&rosterPositive(department.value)&&options.value?.department_id===department.value&&options.value.can_record===true),canCreate=computed(()=>canRecord.value&&draftValid.value&&!saving.value&&(kind.value==='work_rule_policy'||options.value.doctors.some(row=>row.doctor_id===doctor.value))),canReview=computed(()=>allowed.value&&roles.value.includes('super_admin')&&detail.value?.can_review===true);
