function sourceSummary(row){const p=row.payload;return row.source_kind==='qualification'?`原在岗 ${p.employment_status}；资格 ${p.qualification_status}；原有效 ${p.valid_from_at} 至 ${p.valid_until_at??p.expiry_status}；岗位 ${p.authorized_job_keys.join('、')||'原声明为空'}。`:row.source_kind==='duty_interval'?`原班次 ${p.start_at} 至 ${p.end_at}；${p.commitment_status}；${p.work_location}；休息原段 ${p.breaks.length}；完整核实 ${p.breaks_complete}；时间核算 ${p.time_accounting_status}。`:row.source_kind==='availability'?`原可用性 ${p.availability}；${p.start_at} 至 ${p.end_at}；依据类型 ${p.basis_kind}。`:`规则原有效 ${p.effective_from_at} 至 ${p.effective_until_at??p.effective_until_absent_reason}；单次在岗最多 ${quantity(p.max_single_duty_presence_minutes)}；滚动24小时 ${quantity(p.max_work_minutes_rolling_24h)}；滚动7日 ${quantity(p.max_work_minutes_rolling_7d)}；至少休息 ${quantity(p.minimum_rest_minutes)}；固定窗口 ${p.fixed_work_windows.length} 项。`;}
function clearDetail(){detailSeq++;detail.value=null;detailError.value=reviewBasis.value=reason.value='';acting.value=false;}
function clearDraft(){draftOpen.value=false;doctor.value=null;editorKey.value++;draftValid.value=false;saving.value=false;}
function reset(){epoch++;catalogSeq++;optionsSeq++;listSeq++;detailOpen.value=false;clearDetail();clearDraft();departments.value=[];options.value=null;items.value=[];total.value=0;page.value=1;loading.value=false;error.value=notice.value='';department.value=props.departmentId;}
function kindsValid(data){return data?.provider_required===false&&typeof data.can_record==='boolean'&&typeof data.can_review==='boolean'&&Array.isArray(data.source_kinds)&&supportCanonical(data.source_kinds)===supportCanonical(Object.keys(rosterSourceKinds));}
async function catalog(){const ticket=capture(),seq=++catalogSeq;if(!current(ticket))return;try{const response=await getRosterSourceOptions(),data=response.data;if(!current(ticket)||seq!==catalogSeq)return;if(!kindsValid(data)||!Array.isArray(data.departments)||data.departments.length>2000||new Set(data.departments.map(row=>row.department_id)).size!==data.departments.length||data.departments.some(row=>!rosterPositive(row.department_id)||row.name!==null&&typeof row.name!=='string'))throw new Error('排班科室目录与当前授权不一致');departments.value=data.departments;if(props.departmentId){department.value=props.departmentId;await departmentOptions();}await load();}catch(failure){if(current(ticket)&&seq===catalogSeq)error.value=failure?.message||'排班来源授权目录读取失败';}}
async function departmentOptions(){const ticket=capture(),seq=++optionsSeq,dep=department.value;options.value=null;if(!current(ticket)||!rosterPositive(dep))return;try{const response=await getRosterSourceOptions({department_id:dep}),data=response.data;if(!current(ticket)||seq!==optionsSeq||dep!==department.value)return;if(!kindsValid(data)||data.department_id!==dep||data.schema_version!=='roster_fact_v1'||data.personnel_collection_complete_in_database!==true||data.personnel_qualification_verified!==false||!Array.isArray(data.doctors)||data.doctors.length>2000||new Set(data.doctors.map(row=>row.doctor_id)).size!==data.doctors.length||data.doctors.some(row=>!rosterPositive(row.doctor_id)||row.department_id!==dep||row.name!==null&&typeof row.name!=='string'))throw new Error('排班人员目录、真实科室或原资格声明无法核对');options.value=data;}catch(failure){if(current(ticket)&&seq===optionsSeq)error.value=failure?.message||'原科室全部人员目录读取失败';}}
function query(){const pid=doctorFilter.value.trim();if(pid&&(!/^[1-9]\d*$/.test(pid)||!rosterPositive(Number(pid))))throw new Error('原医生ID须为规范正整数');if(department.value!==null&&!rosterPositive(department.value))throw new Error('原科室ID须为正整数');return{...(department.value?{department_id:department.value}:{}),...(pid?{doctor_id:Number(pid)}:{}),...(status.value?{status:status.value}:{}),page:page.value,page_size:20};}
async function load(){const ticket=capture(),seq=++listSeq,key=queryKey();items.value=[];total.value=0;error.value='';if(!current(ticket)||!props.governance&&!department.value)return;loading.value=true;try{const params=query(),response=await(props.governance?getAdminRosterSources({...params,kind:kind.value}):getRosterSources(kind.value,params)),data=response.data;if(!current(ticket)||seq!==listSeq||key!==queryKey())return;if(!Array.isArray(data?.items)||!Number.isSafeInteger(data.total)||data.total<0||data.page!==params.page||data.page_size!==20||data.items.length>20||data.items.length>data.total||new Set(data.items.map(row=>row.source_record_id)).size!==data.items.length||data.items.some(row=>!rosterMetadataValid(row,kind.value,params.department_id??null,params.doctor_id??null)||status.value&&row.status!==status.value))throw new Error('排班原来源元数据目录与所选原范围不一致');items.value=data.items;total.value=data.total;}catch(failure){if(current(ticket)&&seq===listSeq)error.value=failure?.message||'排班原来源目录无法核对';}finally{if(current(ticket)&&seq===listSeq)loading.value=false;}}
async function inspect(original){clearDetail();detailOpen.value=true;const ticket=capture(),seq=detailSeq,key=queryKey();try{const response=await(props.governance?getAdminRosterSource(original.source_record_id):getRosterSource(original.source_kind,original.source_record_id)),row=response.data;if(!current(ticket)||seq!==detailSeq||!detailOpen.value||key!==queryKey())return;if(!roleAudit(row)||!await verifyRosterSource(row,original.source_kind,original.department_id,original.doctor_id,{auditOnly:props.governance})||row.source_record_id!==original.source_record_id||row.content_hash!==original.content_hash||row.governance_hash!==original.governance_hash||['status','revision','reviewed_at','reviewed_by','revoked_at','revoked_by'].some(key=>row[key]!==original[key]))throw new Error('排班原正文、原范围、完整摘要或治理版本已变化，请刷新目录');if(current(ticket)&&seq===detailSeq&&detailOpen.value&&key===queryKey())detail.value=row;}catch(failure){if(current(ticket)&&seq===detailSeq)detailError.value=failure?.message||'原来源详情无法核对';}}
async function save(){if(!canCreate.value)return;const ticket=capture(),dep=department.value,sourceKind=kind.value,subject=sourceKind==='work_rule_policy'?null:doctor.value;let payload;try{payload=editor.value.build();if(!rosterPayloadValid(sourceKind,payload))return;}catch{return;}saving.value=true;error.value='';try{const response=await createRosterSource(sourceKind,{department_id:dep,doctor_id:subject,payload}),row=response.data;if(!current(ticket)||dep!==department.value||sourceKind!==kind.value)return;if(!roleAudit(row)||!await verifyRosterSource(row,sourceKind,dep,subject)||row.status!=='draft'||row.revision!==1||supportCanonical(row.payload)!==supportCanonical(payload))throw new Error('排班原草稿回执与明确原科室、人员、原值或完整摘要不一致');if(!current(ticket)||dep!==department.value||sourceKind!==kind.value)return;clearDraft();notice.value='排班原来源草稿已保存，尚未审核发布、计算候选或改变业务排班。';emit('source-changed',row);await load();}catch(failure){if(current(ticket))error.value=failure?.message||'排班原来源草稿登记失败，请重新核对原范围';}finally{if(current(ticket))saving.value=false;}}
